import { dateFormat } from "@/util/date";
export default {
  name: 'template_ip_mac_jixian_yj',
  props: ['formValue'],
  data: function data() {
    return {
      rules: {
        //校验规则
        disposeResult: [{
          required: true,
          message: '请选择处置结果',
          trigger: 'change'
        }]
      }
    };
  },
  computed: {
    czResults: function czResults() {
      if (this.formValue.warningType == 'IP/MAC变更' || this.formValue.warningType == '基线异常') {
        return ['临时断网', '发起变更'];
      } else if (this.formValue.warningType == '硬件变化') {
        return ['同意变更'];
      }
      return [];
    }
  },
  mounted: function mounted() {},
  methods: {
    validate: function validate(callback) {
      var _this = this;
      this.$refs.submitForm.validate(function (valid) {
        if (callback) {
          //告警处置时间 赋值
          if (valid) {
            _this.formValue.disposeTime = dateFormat(new Date());
          }
          callback(valid);
        }
      });
    }
  }
};
